do $$ declare v_fleet uuid; v_enterprise uuid; begin select id into v_fleet from public.businesses where lower(name)=lower('Kleenest Fleet') and is_demo_test=false limit 1; if v_fleet is null then insert into public.businesses(name,description,business_tier,verification_status,is_demo_test) values('Kleenest Fleet','Fleet-tier business for testing and operating Fleet business capabilities.','fleet','verified',false) returning id into v_fleet; end if; select id into v_enterprise from public.businesses where lower(name)=lower('Kleenest Enterprise') and is_demo_test=false limit 1; if v_enterprise is null then insert into public.businesses(name,description,business_tier,verification_status,is_demo_test) values('Kleenest Enterprise','Enterprise-tier business for testing and operating Enterprise business capabilities.','enterprise','verified',false) returning id into v_enterprise; end if; end $$;
